 77	// RefMutation rebuilds a ref update from its current tip. changed=false is an
 78	// idempotent no-op and returns current without invoking git update-ref.
 79	type RefMutation func(current plumbing.Hash) (next plumbing.Hash, changed bool, err error)
 80	
 81	// RefUpdate describes one compare-and-swap in a multi-ref transaction.
 82	type RefUpdate struct {
 83		Ref      plumbing.ReferenceName
 84		New      plumbing.Hash
 85		Expected plumbing.Hash
 86	}
 87	
 88	// MultiRefMutation rebuilds a set of ref updates from their current tips.
 89	// changed=false is an idempotent no-op.
 90	type MultiRefMutation func(current map[plumbing.ReferenceName]plumbing.Hash) (next map[plumbing.ReferenceName]plumbing.Hash, changed bool, err error)
 91	
 92	type beforeRefCASKey struct{}
 93	
 94	func withBeforeRefCAS(ctx context.Context, hook func()) context.Context {
 95		return context.WithValue(ctx, beforeRefCASKey{}, hook)
