747	// Returns (parentHash, baseTreeHash, error).
748	func (s *ephemeralStore) getOrCreateShadowBranch(branchName, expectedBase string) (plumbing.Hash, plumbing.Hash, error) {
749		refName := plumbing.NewBranchReferenceName(branchName)
750		ref, err := s.repo.Reference(refName, true)
751	
752		if err == nil {
753			// Branch exists
754			commit, err := s.repo.CommitObject(ref.Hash())
755			if err != nil {
756				return plumbing.ZeroHash, plumbing.ZeroHash, fmt.Errorf("failed to get commit object: %w", err)
757			}
758			return ref.Hash(), commit.TreeHash, nil
759		}
760	
761		// Branch doesn't exist, use current HEAD's tree as base
762		head, err := s.repo.Head()
763		if err != nil {
764			return plumbing.ZeroHash, plumbing.ZeroHash, fmt.Errorf("failed to get HEAD: %w", err)
765		}
766		if head.Hash().String() != expectedBase {
767			return plumbing.ZeroHash, plumbing.ZeroHash, fmt.Errorf(
768				"%w: expected base %s, current HEAD %s", ErrShadowBranchMoved, expectedBase, head.Hash(),
769			)
770		}
771	
772		headCommit, err := s.repo.CommitObject(head.Hash())
773		if err != nil {
774			return plumbing.ZeroHash, plumbing.ZeroHash, fmt.Errorf("failed to get HEAD commit: %w", err)
775		}
776	
777		return plumbing.ZeroHash, headCommit.TreeHash, nil
778	}
