 68			require.NoError(t, err)
 69			require.NotNil(t, got)
 70	
 71			got, err = router.Read(ctx, hexID)
 72			require.NoError(t, err)
 73			require.NotNil(t, got, "hex checkpoint on the branch should resolve via fallback under a git-refs primary")
 74		})
 75	
 76		t.Run("git-refs primary: migrated hex in refs resolves from refs first", func(t *testing.T) {
 77			t.Parallel()
