253	func singleSessionBatch(opts WriteOptions) BatchSessions {
254		return BatchSessions{
255			CheckpointID:  opts.CheckpointID,
256			Sessions:      []ReservedSession{ReservedSession(opts)},
257			AuthorName:    opts.AuthorName,
258			AuthorEmail:   opts.AuthorEmail,
259			CommitSubject: opts.CommitSubject,
260		}
261	}
262	
263	func writeSingleSessionViaBatch(ctx context.Context, backend persistentWriteBackend, opts WriteOptions) error {
264		if err := backend.writeBatchSessions(ctx, singleSessionBatch(opts)); err != nil {
265			return err
266		}
267		if opts.CombinedAttribution != nil {
268			return backend.backfillAttribution(ctx, opts.CheckpointID, opts.CombinedAttribution)
269		}
270		return nil
271	}
