355		if err != nil {
356			return plumbing.ZeroHash, err
357		}
358		checkpointSubtree, _, err := s.applyPreparedBatch(ctx, prepared, existing, "")
359		if err != nil {
360			return plumbing.ZeroHash, err
361		}
362		return createCommitAt(ctx, s.repo, checkpointSubtree, parentHash, buildBatchCommitMessage(prepared.request),
363			prepared.request.AuthorName, prepared.request.AuthorEmail, prepared.request.CommitTime)
364	}
