 31	func TestKindRoutingStore_Read(t *testing.T) {
 32		t.Parallel()
 33		ctx := context.Background()
 34	
 35		hexID := id.MustCheckpointID("a1b2c3d4e5f6")
 36		ulidID := id.MustCheckpointID(routingSampleULID)
 37	
 38		t.Run("git-branch primary: hex on branch, ULID still from refs", func(t *testing.T) {
 39			t.Parallel()
 40			_, repo, _ := newTestRepo(t)
 41			branch := NewGitStore(repo, DefaultV1Refs())
 42			refs := newGitRefsStore(repo)
 43			writeRoutingCheckpoint(t, branch, hexID, "hex-on-branch")
 44			writeRoutingCheckpoint(t, refs, ulidID, "ulid-in-refs")
 45	
 46			router := newKindRoutingStore(branch, branch, refs, BackendTypeGitBranch)
 47	
 48			got, err := router.Read(ctx, hexID)
 49			require.NoError(t, err)
 50			require.NotNil(t, got, "hex checkpoint should resolve from the branch")
 51	
 52			got, err = router.Read(ctx, ulidID)
 53			require.NoError(t, err)
 54			require.NotNil(t, got, "ULID checkpoint should resolve from refs even under a git-branch primary")
 55		})
 56	
 57		t.Run("git-refs primary: ULID from refs, pre-migration hex from branch fallback", func(t *testing.T) {
 58			t.Parallel()
 59			_, repo, _ := newTestRepo(t)
 60			branch := NewGitStore(repo, DefaultV1Refs())
 61			refs := newGitRefsStore(repo)
 62			writeRoutingCheckpoint(t, branch, hexID, "hex-on-branch")
 63			writeRoutingCheckpoint(t, refs, ulidID, "ulid-in-refs")
 64	
 65			router := newKindRoutingStore(refs, branch, refs, BackendTypeGitRefs)
 66	
 67			got, err := router.Read(ctx, ulidID)
 68			require.NoError(t, err)
 69			require.NotNil(t, got)
 70	
 71			got, err = router.Read(ctx, hexID)
 72			require.NoError(t, err)
 73			require.NotNil(t, got, "hex checkpoint on the branch should resolve via fallback under a git-refs primary")
 74		})
 75	
 76		t.Run("git-refs primary: migrated hex in refs resolves from refs first", func(t *testing.T) {
 77			t.Parallel()
 78			_, repo, _ := newTestRepo(t)
 79			branch := NewGitStore(repo, DefaultV1Refs())
 80			refs := newGitRefsStore(repo)
 81			migratedHex := id.MustCheckpointID("ffffffffeeee")
 82			writeRoutingCheckpoint(t, refs, migratedHex, "hex-migrated-to-refs")
 83	
 84			router := newKindRoutingStore(refs, branch, refs, BackendTypeGitRefs)
 85	
 86			got, err := router.Read(ctx, migratedHex)
 87			require.NoError(t, err)
 88			require.NotNil(t, got, "a hex checkpoint migrated into refs should resolve under a git-refs primary")
 89		})
 90	
 91		t.Run("git-refs primary: a refs fetch error falls back to the branch", func(t *testing.T) {
 92			t.Parallel()
 93			_, repo, _ := newTestRepo(t)
 94			branch := NewGitStore(repo, DefaultV1Refs())
 95			refs := newGitRefsStore(repo)
 96			// A missing local ref triggers an on-demand fetch; simulate that fetch
 97			// failing (network down) so the refs read returns a hard error rather than
 98			// ErrCheckpointNotFound.
 99			refs.SetRefFetcher(func(context.Context, plumbing.ReferenceName) error {
100				return errors.New("network down")
101			})
102			writeRoutingCheckpoint(t, branch, hexID, "hex-on-branch")
103	
104			router := newKindRoutingStore(refs, branch, refs, BackendTypeGitRefs)
105	
106			got, err := router.Read(ctx, hexID)
107			require.NoError(t, err, "a refs fetch error must not block the branch fallback")
108			require.NotNil(t, got, "hex checkpoint on the branch should resolve even when the refs read errors")
109		})
110	
111		t.Run("a ULID is never read from the branch", func(t *testing.T) {
112			t.Parallel()
113			_, repo, _ := newTestRepo(t)
114			branch := NewGitStore(repo, DefaultV1Refs())
115			refs := newGitRefsStore(repo)
116			// Deliberately put a ULID-named checkpoint on the branch (the wrong place)
117			// and nothing in refs; routing must not find it, proving branch is never
118			// consulted for a ULID.
119			writeRoutingCheckpoint(t, branch, ulidID, "stray-ulid-on-branch")
120	
121			router := newKindRoutingStore(branch, branch, refs, BackendTypeGitBranch)
122	
123			got, err := router.Read(ctx, ulidID)
124			require.NoError(t, err)
125			assert.Nil(t, got, "a ULID must be read only from refs; a stray ULID on the branch must not resolve")
126		})
127	}
