 10	type persistentWriteBackend interface {
 11		writeBatchSessions(ctx context.Context, req BatchSessions) error
 12		backfillTranscript(ctx context.Context, opts UpdateOptions) error
 13		backfillSummary(ctx context.Context, req SessionSummary) error
 14		backfillAttribution(ctx context.Context, checkpointID id.CheckpointID, attribution *Attribution) error
