 25	func dispatchPersistentWrite(ctx context.Context, backend persistentWriteBackend, req WriteRequest) error {
 26		switch r := req.(type) {
 27		case Session:
 28			return writeSingleSessionViaBatch(ctx, backend, WriteOptions(r))
 29		case ReservedSession:
 30			return writeSingleSessionViaBatch(ctx, backend, WriteOptions(r))
 31		case BatchSessions:
 32			return backend.writeBatchSessions(ctx, r)
 33		case SessionTranscript:
 34			return backend.backfillTranscript(ctx, UpdateOptions(r))
 35		case SessionSummary:
 36			return backend.backfillSummary(ctx, r)
 37		case CheckpointAttribution:
 38			return backend.backfillAttribution(ctx, r.CheckpointID, r.Attribution)
 39		default:
 40			return fmt.Errorf("checkpoint: unsupported write request %T", req)
 41		}
