 920			// and a slow/unreachable checkpoint remote must not stall every turn.
 921			// Fall back to the empty orphan, which self-heals immediately.
 922			logging.Debug(ctx, "checkpoint-remote: skipping bootstrap fetch outside explicit enable flow")
