 543	// getMergeBase returns the merge base hash of two commits, or an error if they
 544	// have no common ancestor.
 545	func getMergeBase(ctx context.Context, repoPath, hashA, hashB string) (plumbing.Hash, error) {
 546		ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
 547		defer cancel()
 548	
 549		cmd := exec.CommandContext(ctx, "git", "merge-base", hashA, hashB)
 550		cmd.Dir = repoPath
 551		output, err := cmd.Output()
 552		if err != nil {
 553			var exitErr *exec.ExitError
 554			if errors.As(err, &exitErr) && exitErr.ExitCode() == 1 {
 555				return plumbing.ZeroHash, errNoMergeBase
 556			}
 557			return plumbing.ZeroHash, fmt.Errorf("git merge-base failed: %w", err)
 558		}
 559	
 560		mergeBase := strings.TrimSpace(string(output))
 561		if mergeBase == "" {
 562			return plumbing.ZeroHash, errNoMergeBase
 563		}
 564		return plumbing.NewHash(mergeBase), nil
 565	}
